func NewGitlabClient(baseURL string, token string, rateLimiter rateLimiter) (*gitlab, error) {
	enableNetworkLogging := os.Getenv("LOG_GITLAB_CLIENT_NETWORK_REQUESTS") == "true"

	// Left nil unless a custom transport is needed, so the client keeps its own
	// pooled transport.
	var transport http.RoundTripper
	if baseURL == "https://gitlab.opencode.de" && os.Getenv("NGINX_OPENCODE_PROXY") == "true" {
		proxyURL := os.Getenv("NGINX_OPENCODE_PROXY_URL")
		if proxyURL == "" {
			proxyURL = "http://localhost:8081"
		}
		parsedProxyURL, err := url.Parse(proxyURL)
		if err != nil {
			return nil, fmt.Errorf("invalid NGINX_OPENCODE_PROXY_URL: %w", err)
		}
		slog.Info("Using NGINX OpenCode Proxy for GitLab requests", "proxyURL", fmt.Sprintf("%q", parsedProxyURL.String())) // #nosec G706 -- URL is parsed and quoted to prevent log injection
		baseURL = parsedProxyURL.String()
