	// pool it sets up stays in place.
	options := []client.ClientOptionFunc{
		client.WithBaseURL(baseURL),
		client.WithUserAgent(common.UserAgent()),
		client.WithInterceptor(func(next http.RoundTripper) http.RoundTripper {
			return &rateLimitedTransport{rt: next, rateLimiter: rateLimiter}
		}),
	}
